(function(E){ const x = E["ai-m3"] = E["ai-m3"] || {units:{}}; x.units["ai-10"] = {"grammar":{"id":"c-ai-10-g","level":"B1","course":"ai-internet","unit":"ai-10","title":"Reporting a correction: the draft says, but the sheet says","titleTr":"Düzeltme aktarmak: the draft says, but the sheet says","titleFa":"اصلاح را گزارش بده: the draft says، but the sheet says","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["The draft says X, but the sheet says Y.","The draft says 5 days, but the sheet says 10."],["It should say + X","It should say 10 days."],["a 12-month warranty","a 12-month warranty, not a 12-months warranty"]]},"wrong":"We offer a 12-months warranty.","right":"We offer a 12-month warranty.","blank":{"sentence":"The price includes a ___ warranty.","word":"2-year","distractors":["2-years","2 years"]},"wrong2":"The draft says 5 days, and the sheet tells 10.","right2":"The draft says 5 days, but the sheet says 10.","blank2":{"sentence":"The draft says Monday, ___ the sheet says Friday.","word":"but","distractors":["so","because"],"hint2":{"en":"The two halves say different things. Which small word shows a difference between them?","tr":"Cümlenin iki yarısı farklı şeyler söylüyor. Hangi küçük kelime aradaki farkı gösterir?","fa":"دو نیمه‌ی جمله دو چیز متفاوت می‌گویند. کدام کلمه‌ی کوچک تفاوتشان را نشان می‌دهد؟"},"why":{"en":"but: it shows the difference between the draft and the sheet. So would give a result, and because a reason.","tr":"but: taslak ile sayfa arasındaki farkı gösterir. so bir sonuç, because ise bir neden verir.","fa":"جواب ⁨but⁩ است، چون تفاوت پیش‌نویس و برگه را نشان می‌دهد. ⁨so⁩ نتیجه را می‌گوید و ⁨because⁩ دلیل را."}},"expParts":{"tryFrom":"blank","rule":[{"en":"Use but to show the difference.","tr":"Farkı but ile göster.","fa":"تفاوت را با but نشان بده.","ex":"It says May, but the sheet says June."},{"en":"A number + noun before a noun has no -s.","tr":"Sayı + isim, bir ismin önünde -s almaz.","fa":"وقتی عدد و اسم پیش از اسم دیگری می‌آیند، ⁨-s⁩ نمی‌گیرند.","ex":"a 12-month warranty"}],"test":{"en":"Is the number phrase before a noun? Drop the -s and add a hyphen.","tr":"Sayılı ifade ismin önünde mi? -s'yi at, tire ekle.","fa":"عبارت عددی پیش از اسم است؟ ⁨-s⁩ را حذف کن و خط‌تیره بگذار."}},"errorWatch":[{"find":["12-months warranty","2-years warranty"],"fix":{"en":"Before a noun, use no -s: \"a 2-year warranty\".","tr":"İsimden önce -s yok: \"a 2-year warranty\".","fa":"پیش از اسم ⁨-s⁩ نیاور: «⁨a 2-year warranty⁩»."}}]},"b2":{"id":"c-ai-10-b2","level":"B2","course":"ai-internet","unit":"ai-10","track":"B2","title":"Exact report language: whereas, I could not find","titleTr":"Kesin rapor dili: whereas, I could not find","titleFa":"زبان دقیق گزارش: whereas، I could not find","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["whereas","The draft gives 5 days, whereas the sheet gives 10."],["I could not find","I could not find this claim in the sheet."]]},"wrong":"The draft gives 5 days whereas of the sheet gives 10.","right":"The draft gives 5 days, whereas the sheet gives 10.","blank":{"sentence":"It says free, ___ the sheet says 20 euros.","word":"whereas","distractors":["because","also"]},"wrong2":"I could not to find it.","right2":"I could not find it.","blank2":{"sentence":"I could not ___ this claim.","word":"confirm","distractors":["to confirm","confirming"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Whereas shows a contrast in one sentence.","tr":"whereas tek cümlede karşıtlık gösterir.","fa":"با whereas تضاد دو چیز را در یک جمله نشان می‌دهی.","ex":"It says free, whereas the sheet says 20 euros."},{"en":"Use could not for what you tried and failed.","tr":"Denenip olmayan şey için could not kullan.","fa":"برای چیزی که امتحان کردی و نشد از could not استفاده کن.","ex":"I could not confirm it."}],"test":{"en":"Two facts in contrast? Use whereas.","tr":"İki bilgi karşıt mı? whereas kullan.","fa":"دو واقعیت در تضادند؟ از whereas استفاده کن."}},"errorWatch":[{"find":["could not to"],"fix":{"en":"After could not, use the base verb.","tr":"could not'tan sonra yalın fiil gelir.","fa":"بعد از could not شکل ساده‌ی فعل می‌آید."}}],"useIn":{"en":"B2: write your change note with whereas and I could not find.","tr":"B2: Değişiklik notunu whereas ve I could not find ile yaz.","fa":"B2: یادداشت تغییرت را با whereas و I could not find بنویس."},"exitItem":{"from":"ai-10","kind":"blank","prompt":"I could not ___ this number in the sheet.","options":["find","to find","finding"],"correct":0,"why":{"en":"find: after 'could not', use the plain verb. 'To find' and 'finding' don't follow could.","tr":"find: 'could not'tan sonra yalın fiil gelir. 'To find' ve 'finding' could'dan sonra gelmez.","fa":"find درست است، چون بعد از could not فعل ساده می‌آید. to find و finding بعد از could نمی‌آیند."},"hint2":{"en":"After could not, which form of the verb comes: with to, with -ing, or the verb on its own?","tr":"could not ifadesinden sonra fiil hangi biçimde gelir: to ile mi, -ing ile mi, yoksa yalın hâliyle mi?","fa":"بعد از ⁨could not⁩ فعل به چه شکلی می‌آید: با ⁨to⁩، با ⁨-ing⁩ یا خودِ فعل به‌تنهایی؟"}}},"vocab":{"id":"c-ai-10-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-10","goals":["career"],"title":{"en":"Checking a draft","tr":"Taslak kontrol etmek","fa":"بررسی پیش‌نویس"},"cards":[{"word":"order line","sentence":"Check the date on the order line.","meaning":{"en":"One row in an order, with product and price.","tr":"Siparişte ürün ve fiyatın olduğu satır.","fa":"یک ردیف از سفارش، با محصول و قیمت."}},{"word":"warranty","sentence":"It has a 12-month warranty.","meaning":{"en":"A maker's promise to fix a product.","tr":"Üreticinin ürünü onarma sözü.","fa":"قول سازنده برای تعمیر محصول."}},{"word":"promise","sentence":"The draft makes a promise we can't keep.","meaning":{"en":"Saying you will surely do something.","tr":"Bir şeyi kesin yapacağını söylemek.","fa":"اینکه بگویی حتماً کاری را انجام می‌دهی."}},{"word":"claim","sentence":"I can't find this claim in the sheet.","meaning":{"en":"Something said to be true.","tr":"Doğru olduğu söylenen şey.","fa":"چیزی که ادعا می‌کنند درست است."}}]},"judge":{"id":"c-ai-10-j","course":"ai-internet","unit":"ai-10","type":"judge","title":{"en":"Keep, Correct, or Remove or ask?","tr":"Keep, Correct, Remove or ask?","fa":"Keep، Correct یا Remove or ask؟"},"prompt":"Order sheet: \"Order 2210. 40 chairs, grey. Delivery 12 March. Warranty 12 months. Price 3,200 euros, excluding delivery.\" Example AI draft below. Check each line.","parts":["Keep","Correct","Remove or ask"],"instruction":{"en":"Choose one result for each line.","tr":"Her satır için bir sonuç seç.","fa":"برای هر خط یک نتیجه انتخاب کن."},"mode":"single","items":[{"by":"Example AI answer","answer":"Your order of 40 grey chairs is confirmed.","present":["Keep"],"fix":{"en":"The sheet says the same.","tr":"Sayfa aynısını söylüyor.","fa":"در برگه هم همین آمده است."}},{"by":"Example AI answer","answer":"They will arrive on 21 March.","present":["Correct"],"fix":{"en":"The sheet says 12 March.","tr":"Sayfada 12 March yazıyor.","fa":"در برگه 12 March آمده است."}},{"by":"Example AI answer","answer":"The price of 3,200 euros includes free delivery.","present":["Correct"],"fix":{"en":"The sheet says excluding delivery.","tr":"Sayfada excluding delivery yazıyor.","fa":"در برگه excluding delivery آمده است."}},{"by":"Example AI answer","answer":"We also give you a free cushion with each chair.","present":["Remove or ask"],"fix":{"en":"It is not on the sheet.","tr":"Sayfada yok.","fa":"این در برگه نیامده است."}},{"by":"Example AI answer","answer":"The chairs have a 12-month warranty.","present":["Keep"],"fix":{"en":"Same fact.","tr":"Aynı bilgi.","fa":"همان اطلاعات است."}}]},"speaking":{"id":"ai-10","course":"ai-internet","unit":"ai-10","topic":{"en":"Explain what you changed","tr":"Neyi değiştirdiğini açıkla","fa":"توضیح بده چه چیزی را عوض کردی"},"warmup":{"en":"Have you ever sent a wrong date or number? What happened?","tr":"Hiç yanlış tarih ya da sayı gönderdin mi? Ne oldu?","fa":"تا حالا تاریخ یا عدد غلط فرستاده‌ای؟ چه شد؟"},"questions":[{"en":"Tell your manager what was wrong in the draft and what you did.","tr":"Yöneticine taslakta neyin yanlış olduğunu ve ne yaptığını anlat.","fa":"به مدیرت بگو چه چیزی در پیش‌نویس غلط بود و چه کردی."},{"en":"A colleague says: \"The English is perfect, so just send it.\" Reply.","tr":"Bir meslektaşın diyor ki: \"The English is perfect, so just send it.\" Yanıtla.","fa":"همکارت می‌گوید: «The English is perfect, so just send it.» جواب بده."},{"en":"The sheet says \"valid until 30 June\". The draft says \"until the end of June\". Say your result and why.","tr":"Sayfada \"valid until 30 June\" yazıyor. Taslakta \"until the end of June\" yazıyor. Sonucunu ve nedenini söyle.","fa":"در برگه آمده «valid until 30 June» و در پیش‌نویس «until the end of June». بگو نتیجه‌ات چیست و چرا."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"The draft says..., but the sheet says...","meaning":{"en":"Shows the difference.","tr":"Farkı gösterir.","fa":"تفاوت را نشان می‌دهد."}},{"phrase":"I can't find this, so I removed it.","meaning":{"en":"Explains a removal.","tr":"Bir çıkarmayı açıklar.","fa":"می‌گوید چرا آن را حذف کردی."}}],"model":"I checked the AI draft against the order sheet before I sent it. The draft says the twenty-first of March, but the sheet says the twelfth, so I corrected it. It also says delivery is free, but the sheet says excluding delivery. I can't find the free cushion on the sheet, so I removed it. Now it's safe to send.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I gave the source for each change.","tr":"Her değişiklik için kaynağı söyledim.","fa":"برای هر تغییر منبع را گفتم."}]},"writing":{"id":"c-ai-10-w","title":{"en":"Correct a reply and write a change note","tr":"Yanıtı düzelt, değişiklik notu yaz","fa":"جواب را اصلاح کن و یادداشت تغییر بنویس"},"course":"ai-internet","unit":"ai-10","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"ai-final-2","prompt":{"en":"Order sheet: \"Order 2210. 40 chairs, grey. Delivery 12 March. Warranty 12 months. Price 3,200 euros, excluding delivery.\" Correct this draft against the sheet: \"Your 40 grey chairs arrive on 21 March. The price of 3,200 euros includes free delivery. Each chair comes with a free cushion.\" Then write a short change note.","tr":"Sipariş sayfası: \"Order 2210. 40 chairs, grey. Delivery 12 March. Warranty 12 months. Price 3,200 euros, excluding delivery.\" Bu taslağı sayfaya göre düzelt: \"Your 40 grey chairs arrive on 21 March. The price of 3,200 euros includes free delivery. Each chair comes with a free cushion.\" Sonra kısa bir değişiklik notu yaz.","fa":"برگه‌ی سفارش: «Order 2210. 40 chairs, grey. Delivery 12 March. Warranty 12 months. Price 3,200 euros, excluding delivery.» این پیش‌نویس را با این برگه اصلاح کن: «Your 40 grey chairs arrive on 21 March. The price of 3,200 euros includes free delivery. Each chair comes with a free cushion.» بعد یک یادداشت تغییر کوتاه بنویس."},"model":"Your 40 grey chairs arrive on 12 March. The price is 3,200 euros, excluding delivery.\n\nChange note: The draft says 21 March, but the sheet says 12 March. The draft says free delivery, but the sheet says excluding delivery. I can't find the free cushion on the sheet, so I removed it.","frame":"Your 40 grey chairs arrive on ___. The price is ___.\n\nChange note: The draft says ___, but the sheet says ___. I can't find ___, so I removed it.","words":[{"word":"but the sheet says"},{"word":"so I removed it"}],"minWords":35,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Write the note with whereas and I could not find.","tr":"B2 yolu: hazır çerçeve yok. Notu whereas ve I could not find ile yaz.","fa":"مسیر B2: چارچوب آماده نداری. یادداشت را با whereas و I could not find بنویس."},"own":{"en":"Now check a short draft of your own against its source, with made-up details.","tr":"Şimdi kendi kısa taslağını uydurma ayrıntılarla kaynağına göre kontrol et.","fa":"حالا یک پیش‌نویس کوتاه از کار خودت را با منبعش مقایسه کن و جزئیات را ساختگی بنویس."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Ask your tool for a reply from an order line. Then check it line by line.","tr":"Aracından bir sipariş satırına göre yanıt iste. Sonra satır satır kontrol et.","fa":"از ابزارت بخواه از روی یک خط سفارش جواب بنویسد. بعد خط‌به‌خط بررسی‌اش کن."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Use the example draft in this lesson. The check is the same.","tr":"Bu dersteki örnek taslağı kullan. Kontrol aynı.","fa":"از پیش‌نویس نمونه‌ی این درس استفاده کن. روش بررسی فرقی نمی‌کند."},"noTool":true}],"parts":[{"t":{"en":"The corrected reply","tr":"Düzeltilmiş yanıt","fa":"جواب اصلاح‌شده"},"find":["12 march","excluding delivery","arrive on"],"sample":"your 40 grey chairs arrive on 12 March · 3,200 euros, excluding delivery"},{"t":{"en":"Each change, with but the sheet says","tr":"Her değişiklik, but the sheet says ile","fa":"هر تغییر، با ⁨but the sheet says⁩"},"find":["but the sheet says","the draft says"],"sample":"the draft says 21 March, but the sheet says 12 March"},{"t":{"en":"What you removed, and why","tr":"Neyi çıkardığın ve nedeni","fa":"چه چیزی را حذف کردی و چرا"},"find":["so i removed it","i removed","i can't find","i cannot find","not on the sheet"],"sample":"I can't find the free cushion on the sheet, so I removed it"}]},"exit":{"id":"c-ai-10-x","course":"ai-internet","unit":"ai-10","type":"exit","items":[{"from":"ai-10","kind":"mcq","prompt":"Why can't you judge an AI draft by your ear?","options":["Your ear only works in your own language.","It can sound right and still be wrong.","AI drafts are wrong in most sentences."],"correct":1,"why":{"en":"It can sound right and still be wrong: fluent sentences can carry a wrong date or number, so you check with your source. 'AI drafts are wrong in most sentences' goes too far; most lines may be fine.","tr":"It can sound right and still be wrong: akıcı cümleler yanlış bir tarih ya da sayı taşıyabilir; bu yüzden kaynağınla kontrol edersin. 'AI drafts are wrong in most sentences' abartılıdır; satırların çoğu doğru olabilir.","fa":"It can sound right and still be wrong درست است، چون جمله‌ی روان هم می‌تواند تاریخ یا عدد غلط داشته باشد؛ پس با منبعت بررسی می‌کنی. اینکه بیشتر جمله‌های پیش‌نویس غلط است اغراق است؛ شاید بیشتر خط‌ها درست باشند."},"point":1,"hint2":{"en":"Smooth English and correct facts are two different things. Which one can your ear check?","tr":"Akıcı İngilizce ile doğru bilgi iki ayrı şeydir. Kulağın hangisini kontrol edebilir?","fa":"انگلیسی روان و اطلاعات درست دو چیز جدا هستند. گوشت کدام را می‌تواند بررسی کند؟"}},{"from":"ai-10","kind":"mcq","prompt":"What should you look at first in a draft?","options":["The length and the first greeting","Numbers, names, dates and promises","Commas, capitals and spelling mistakes"],"correct":1,"why":{"en":"Numbers, names, dates and promises: these errors cost the most if they reach a customer. Commas and spelling matter too, but you check them later.","tr":"Numbers, names, dates and promises: bu hatalar bir müşteriye ulaşırsa en pahalıya patlar. Virgül ve yazım da önemlidir ama onlara sonra bakarsın.","fa":"Numbers, names, dates and promises درست است، چون اگر این اشتباه‌ها به دست مشتری برسند، بیشترین هزینه را دارند. ویرگول و املا هم مهم‌اند، ولی آن‌ها را بعداً بررسی می‌کنی."},"point":1,"hint2":{"en":"Which errors cost the most if they reach a customer: a comma, or a wrong fact such as a date?","tr":"Bir müşteriye ulaştığında en pahalıya mal olan hatalar hangileri: bir virgül mü, yoksa tarih gibi yanlış bir bilgi mi?","fa":"کدام اشتباه‌ها اگر به مشتری برسند گران‌تر تمام می‌شوند: یک ویرگول یا واقعیتی غلط مثل یک تاریخ؟"}},{"from":"ai-10","kind":"blank","prompt":"We offer a ___ warranty.","options":["24-month","24-months","24 of months"],"correct":0,"why":{"en":"24-month: a number + noun before another noun works like an adjective, so it has a hyphen and no -s. '24-months' adds the -s that adjectives never take.","tr":"24-month: başka bir isimden önce gelen sayı + isim sıfat gibi çalışır; kısa çizgi alır, -s almaz. '24-months' sıfatların asla almadığı -s'yi ekler.","fa":"24-month درست است، چون عدد و اسمی که قبل از اسم دیگری می‌آید مثل صفت کار می‌کند: خط تیره می‌گیرد و s نمی‌گیرد. 24-months یک s اضافه دارد که صفت هیچ‌وقت نمی‌گیرد."},"point":3,"hint2":{"en":"The number and its noun come before another noun, so they work like one adjective. Can an adjective be plural?","tr":"Sayı ve ismi başka bir isimden önce geliyor, yani tek bir sıfat gibi çalışıyorlar. Bir sıfat çoğul olabilir mi?","fa":"عدد و اسمش قبل از یک اسم دیگر آمده‌اند، پس مثل یک صفت کار می‌کنند. آیا صفت می‌تواند جمع باشد؟"}},{"from":"ai-9","kind":"blank","prompt":"Once you have ___ the file, list the dates.","options":["reading","to read","read"],"correct":2,"why":{"en":"read: 'once you have' is followed by the past participle, and the participle of read is read. 'Reading' and 'to read' don't follow have here.","tr":"read: 'once you have'den sonra fiilin üçüncü hâli gelir; read'in üçüncü hâli de read'dir. 'Reading' ve 'to read' burada have'den sonra gelmez.","fa":"read درست است، چون بعد از once you have اسم مفعول می‌آید و اسم مفعول read هم read است. reading و to read اینجا بعد از have نمی‌آیند."},"point":4,"hint2":{"en":"Once you have is followed by the past participle, as in I have finished. Which option is that form of the verb?","tr":"once you have ifadesinden sonra fiilin üçüncü hâli gelir, I have finished örneğindeki gibi. Hangi seçenek fiilin bu hâli?","fa":"بعد از ⁨once you have⁩ شکل سوم فعل (اسم مفعول) می‌آید، مثل ⁨I have finished.⁩ کدام گزینه همین شکل فعل است؟"}},{"from":"ai-6","kind":"mcq","prompt":"Answer is about the wrong thing. What do you do?","options":["Fix the prompt and start a new chat.","Ask for a shorter answer in that chat.","Add a thank-you and send the answer."],"correct":0,"why":{"en":"Fix the prompt and start a new chat: an answer about the wrong topic needs a new start, not a follow-up. A shorter answer in the same chat is still about the wrong thing.","tr":"Fix the prompt and start a new chat: yanlış konudaki bir cevap devam mesajı değil, yeni bir başlangıç ister. Aynı sohbette daha kısa bir cevap yine yanlış konudadır.","fa":"Fix the prompt and start a new chat درست است، چون جوابی که درباره‌ی موضوع اشتباه است شروع تازه لازم دارد، نه پیام بعدی. جواب کوتاه‌تر در همان گفت‌وگو هنوز درباره‌ی موضوع اشتباه است."},"point":4,"hint2":{"en":"Is this answer close, or about the wrong thing? A follow-up only helps when the answer is close.","tr":"Bu yanıt yakın mı, yoksa yanlış konuyla mı ilgili? Takip mesajı yalnızca yanıt yakınsa işe yarar.","fa":"این جواب نزدیک است یا درباره‌ی موضوعی اشتباه؟ پیام بعدی فقط وقتی کمک می‌کند که جواب نزدیک باشد."}},{"from":"ai-3","kind":"mcq","prompt":"Which is personal data?","options":["The name of the capital city","A customer's phone number","Our company's public address"],"correct":1,"why":{"en":"A customer's phone number: it belongs to a real person who can be identified. Your company's public address is about a business, and it is already public.","tr":"A customer's phone number: kimliği belirlenebilen gerçek bir kişiye aittir. Şirketinin herkese açık adresi bir işletmeyle ilgilidir ve zaten açıktır.","fa":"A customer's phone number درست است، چون به یک آدم واقعی تعلق دارد که می‌شود او را شناخت. آدرس عمومی شرکت درباره‌ی یک کسب‌وکار است و از قبل عمومی است."},"point":4},{"from":"ai-9","kind":"mcq","prompt":"You asked a tool for a total. Why ask for the formula too?","options":["So the answer looks more professional.","So the tool works a little faster.","So you can see how it got there."],"correct":2,"why":{"en":"So you can see how it got there: then you can test the formula on a few rows. A formula doesn't make the tool faster, and looking professional is not proof.","tr":"So you can see how it got there: böylece formülü birkaç satırda test edebilirsin. Formül aracı hızlandırmaz; profesyonel görünmek de kanıt değildir.","fa":"So you can see how it got there درست است، چون آن وقت می‌توانی فرمول را روی چند ردیف امتحان کنی. فرمول ابزار را سریع‌تر نمی‌کند و ظاهر حرفه‌ای هم مدرک نیست."},"point":2,"hint2":{"en":"A total alone looks neat even when it is wrong. What does the formula show you that the total doesn't?","tr":"Tek başına bir toplam yanlış olsa bile düzgün görünür. Formül sana toplamın göstermediği neyi gösterir?","fa":"جمعِ تنها حتی وقتی غلط باشد مرتب به نظر می‌رسد. فرمول چه چیزی را نشانت می‌دهد که جمع نشان نمی‌دهد؟"}}]},"explain":{"id":"c-ai-10-e","course":"ai-internet","unit":"ai-10","type":"explain","level":"B1","title":{"en":"Find it before the customer does","tr":"Müşteriden önce bul","fa":"پیش از مشتری پیدایش کن"},"objective":{"en":"After this lesson, you can check an AI draft line by line against your source and report what you changed.","tr":"Bu dersin sonunda bir yapay zekâ taslağını satır satır kaynağınla karşılaştırabilecek ve değişikliklerini aktarabileceksin.","fa":"بعد از این درس می‌توانی پیش‌نویس هوش مصنوعی را خط‌به‌خط با منبعت مقایسه کنی و تغییرهایت را گزارش بدهی."},"hook":{"en":"An AI draft may be better English than yours. So it can sound right and still be wrong. One wrong date can cost you a customer.","tr":"Yapay zekâ taslağının İngilizcesi seninkinden iyi olabilir. Yani kulağa doğru gelip yanlış olabilir. Tek bir yanlış tarih müşteriye mal olabilir.","fa":"پیش‌نویس هوش مصنوعی شاید انگلیسی بهتری از تو داشته باشد. پس ممکن است درست به نظر بیاید و باز هم غلط باشد. یک تاریخ غلط می‌تواند به قیمت از دست دادن مشتری تمام شود."},"before":{"en":"The sheet says delivery 12 March; the draft says 21 March. Write your change note.","tr":"Sayfada teslimat 12 Mart yazıyor; taslakta 21 Mart. Değişiklik notunu yaz.","fa":"در برگه نوشته تحویل ۱۲ مارس، ولی در پیش‌نویس ۲۱ مارس. یادداشت تغییرت را بنویس."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"20"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"head":{"en":"Go line by line","tr":"Satır satır ilerle","fa":"خط‌به‌خط جلو برو"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"The tool doesn't know your order. Its sentences can be smooth and its facts wrong, so your ear can't find the error. Only your source can.","tr":"Araç senin siparişini bilmez. Cümleleri akıcı, bilgileri yanlış olabilir; bu yüzden kulağın hatayı bulamaz. Hatayı ancak kaynağın gösterir.","fa":"ابزار سفارش تو را نمی‌شناسد. ممکن است جمله‌هایش روان باشند و اطلاعاتش غلط، پس از روی روان بودن جمله نمی‌توانی خطا را پیدا کنی. فقط منبعت آن را نشان می‌دهد."},"steps":[{"en":"Look first at numbers, names, dates and promises.","tr":"Önce sayılara, adlara, tarihlere ve sözlere bak.","fa":"اول به عددها، نام‌ها، تاریخ‌ها و قول‌ها نگاه کن.","ex":"5 days? Free return? 2-year warranty?"},{"en":"Keep: the source says the same.","tr":"Keep: Kaynak aynısını söylüyor.","fa":"اگر منبع همین را می‌گوید، نتیجه ⁨Keep⁩ است.","ex":"Source: 14 May. Draft: 14 May."},{"en":"Correct: the source says something else.","tr":"Correct: Kaynak başka bir şey söylüyor.","fa":"اگر منبع چیز دیگری می‌گوید، نتیجه ⁨Correct⁩ است.","ex":"Source: 10 days. Draft: 5 days."},{"en":"Remove or ask: you can't find it in the source.","tr":"Remove or ask: Kaynakta bulamıyorsun.","fa":"اگر در منبع پیدایش نمی‌کنی، نتیجه ⁨Remove or ask⁩ است.","ex":"Draft: free shipping. Source: nothing."}],"tip":{"en":"The same fact in other words is fine. \"Valid until 30 June\" and \"until the end of June\" are both right.","tr":"Aynı bilgi başka kelimelerle sorun değildir. \"Valid until 30 June\" ve \"until the end of June\" ikisi de doğru.","fa":"اگر همان اطلاعات با کلمه‌های دیگری آمده باشد، اشکالی ندارد. «⁨Valid until 30 June⁩» و «⁨until the end of June⁩» هر دو درست‌اند."}},{"head":{"en":"Let a tool help you check","tr":"Kontrolde araçtan yardım al","fa":"برای بررسی از ابزار کمک بگیر"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"A list is faster to check than a whole email, and a tool can make the list. You still read the source yourself.","tr":"Bir listeyi kontrol etmek bütün bir e-postayı kontrol etmekten hızlıdır ve listeyi araç hazırlayabilir. Kaynağı yine sen okursun.","fa":"بررسی یک فهرست سریع‌تر از بررسی یک ایمیل کامل است و ابزار می‌تواند فهرست را بسازد. ولی منبع را باید خودت بخوانی."},"phrases":[{"phrase":"List every number, name, date and promise in this draft. Next to each one, quote the line from the source that supports it. If there is none, write \"not found\".\nDraft: [paste]\nSource: [paste]","meaning":{"en":"A prompt to copy. It shows you what to check.","tr":"Kopyalanacak prompt. Neyi kontrol edeceğini gösterir.","fa":"پرامپت برای کپی. نشان می‌دهد چه چیزی را بررسی کنی."},"copy":true}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Reporting a correction: the draft says, but the sheet says","tr":"Düzeltme aktarmak: the draft says, but the sheet says","fa":"اصلاح را گزارش بده: ⁨the draft says⁩، ⁨but the sheet says⁩"},"steps":[{"en":"Use but to show the difference.","tr":"Farkı but ile göster.","fa":"تفاوت را با ⁨but⁩ نشان بده.","ex":"It says May, but the sheet says June."},{"en":"A number + noun before a noun has no -s.","tr":"Sayı + isim, bir ismin önünde -s almaz.","fa":"وقتی عدد و اسم پیش از اسم دیگری می‌آیند، ⁨-s⁩ نمی‌گیرند.","ex":"a 12-month warranty"}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["The draft says X, but the sheet says Y.","The draft says 5 days, but the sheet says 10."],["It should say + X","It should say 10 days."],["a 12-month warranty","a 12-month warranty, not a 12-months warranty"]]},"wrong":"The draft is saying 30 June, but the sheet is saying 15 June.","right":"The draft says 30 June, but the sheet says 15 June."}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Check one line","tr":"Bir satırı kontrol et","fa":"یک خط را بررسی کن"},"item":"Source: \"Delivery in 10 days.\"\nDraft: \"We will deliver in 5 days.\"","answer":"Correct. The draft says 5 days, but the sheet says 10, so I corrected it.","walk":[{"en":"Find the same fact in the source.","tr":"Aynı bilgiyi kaynakta bul.","fa":"همان اطلاعات را در منبع پیدا کن."},{"en":"Give the result: Keep, Correct, or Remove or ask.","tr":"Sonucu ver: Keep, Correct, Remove or ask.","fa":"نتیجه را بگو: ⁨Keep⁩، ⁨Correct⁩ یا ⁨Remove or ask⁩."},{"en":"Say what you changed, in one sentence.","tr":"Neyi değiştirdiğini tek cümleyle söyle.","fa":"در یک جمله بگو چه چیزی را عوض کردی."}],"why":{"en":"The draft sounds fine, and only the source shows the error. One sentence with the source's number tells your reader what you changed and why.","tr":"Taslak kulağa iyi gelir, hatayı yalnızca kaynak gösterir. Kaynağın sayısını veren tek cümle, okuyucuna neyi neden değiştirdiğini söyler.","fa":"پیش‌نویس خوب به نظر می‌رسد و فقط منبع خطا را نشان می‌دهد. یک جمله با عدد منبع به خواننده می‌گوید چه چیزی را عوض کردی و چرا."},"cut":["5 days"],"cutHint":{"en":"Tap the fact that doesn't match the source.","tr":"Kaynakla uyuşmayan bilgiye dokun.","fa":"روی واقعیتی بزن که با منبع جور درنمی‌آید."}},"quick":{"prompt":"The draft says \"Installation is included.\" The order sheet says nothing about installation. What do you do?","options":["Remove it or ask","Keep it","Correct it"],"correct":0,"why":{"en":"Remove it or ask: you can't find it in the source, so it may be invented. Correct is for a fact the sheet gives differently; Keep is for one it gives the same.","tr":"Remove it or ask: kaynakta bulamıyorsun, yani uydurma olabilir. Correct, sayfanın farklı verdiği bir bilgi içindir; Keep ise aynısını verdiği bilgi için.","fa":"جواب ⁨Remove it or ask⁩ است، چون آن را در منبع پیدا نمی‌کنی و شاید ساختگی باشد. ⁨Correct⁩ برای واقعیتی است که برگه جور دیگری گفته و ⁨Keep⁩ برای واقعیتی که برگه همان را گفته."}},"remember":{"en":"Check with your source, not your ear. Each line gets one result: Keep, Correct, or Remove or ask. You can now check a draft line by line and say what you changed and why.","tr":"Kulağınla değil, kaynağınla kontrol et. Her satır bir sonuç alır: Keep, Correct, Remove or ask. Artık bir taslağı satır satır kontrol edebilir, neyi neden değiştirdiğini söyleyebilirsin.","fa":"با منبعت بررسی کن، نه با اینکه به گوشت درست می‌آید. هر خط یک نتیجه می‌گیرد: ⁨Keep⁩، ⁨Correct⁩ یا ⁨Remove or ask⁩. حالا می‌توانی پیش‌نویس را خط‌به‌خط بررسی کنی و بگویی چه چیزی را عوض کردی و چرا."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Exact report language: whereas, I could not find","tr":"Kesin rapor dili: whereas, I could not find","fa":"زبان دقیق گزارش: ⁨whereas⁩، ⁨I could not find⁩"},"steps":[{"en":"Whereas shows a contrast in one sentence.","tr":"whereas tek cümlede karşıtlık gösterir.","fa":"با ⁨whereas⁩ تضاد دو چیز را در یک جمله نشان می‌دهی.","ex":"It says free, whereas the sheet says 20 euros."},{"en":"Use could not for what you tried and failed.","tr":"Denenip olmayan şey için could not kullan.","fa":"برای چیزی که امتحان کردی و نشد از ⁨could not⁩ استفاده کن.","ex":"I could not confirm it."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["whereas","The draft gives 5 days, whereas the sheet gives 10."],["I could not find","I could not find this claim in the sheet."]]},"body":{"en":"B2: write your change note with whereas and I could not find.","tr":"B2: Değişiklik notunu whereas ve I could not find ile yaz.","fa":"⁨B2⁩: یادداشت تغییرت را با ⁨whereas⁩ و ⁨I could not find⁩ بنویس."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
